output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_into_single_file_aisles",
    "text": "Agents must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartEntryToSingleFileShelfAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntryToSingleFileShelfAisle"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart at an aisle mouth, the agent is obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "wideOpenStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCartAtStagingArea": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "wideOpenStagingArea"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtStagingArea": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "wideOpenStagingArea"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtStagingArea",
      "discharge": "retrieveCartAtStagingArea"
    }
  },
  {
    "id": "park_carts_only_in_wide_staging_areas",
    "text": "Carts may only be set down in wide open staging areas, not beside shelves or inside narrow aisles.",
    "abstraction": {
      "state_properties": {
        "wideOpenStagingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDropOutsideStagingArea": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "wideOpenStagingArea"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartDropOutsideStagingArea"
    }
  },
  {
    "id": "no_cart_item_interaction_in_single_file_aisles",
    "text": "Shelf interactions inside single-file shelf aisles must be done without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "cartless_nonpickup_interactions_only_in_single_file_aisles",
    "text": "If the agent is not holding a cart, non-cart-pickup interactions should occur only in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartlessNonPickupInteractionOutsideSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessNonPickupInteractionOutsideSingleFileAisle"
    }
  },
  {
    "id": "return_from_single_file_aisle_on_foot",
    "text": "After entering a single-file shelf aisle without a cart, the agent is obliged to return on foot to an open non-shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openNonShelfAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "leaveSingleFileAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "openNonShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileAisleOnFoot",
      "discharge": "leaveSingleFileAisleOnFoot"
    }
  },
  {
    "id": "one_way_wide_aisles_no_west_with_cart",
    "text": "In wide horizontal shopping aisles, carts should follow the one-way flow and not move west.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  }
]
